import Joi from 'joi';
import { MAX_LIST_ITEMS, methodology, optionalText, textList, titledList } from './service.validator.js';

export const CENTER_STATUSES = ['active', 'inactive', 'coming_soon'];

// Create and update share the schema: the admin form always sends the full center.
// The id is generated by the database ("center-N") and never changes.
export const centerSchema = Joi.object({
    title: Joi.string().trim().min(2).max(255).required()
        .messages({ 'string.empty': 'اسم المركز مطلوب', 'any.required': 'اسم المركز مطلوب', 'string.min': 'اسم المركز حرفين على الأقل' }),
    status: Joi.string().valid(...CENTER_STATUSES).default('active')
        .messages({ 'any.only': 'حالة المركز غير صالحة' }),
    imageUrl: optionalText(512),
    price: Joi.number().min(0).max(9999999999.99).precision(2).default(0)
        .messages({ 'number.base': 'السعر يجب أن يكون رقمًا', 'number.min': 'السعر لا يمكن أن يكون سالبًا' }),
    responseTime: optionalText(100),
    executionDuration: optionalText(100),
    overview: Joi.string().trim().min(10).max(20000).required()
        .messages({ 'string.empty': 'النظرة العامة مطلوبة', 'any.required': 'النظرة العامة مطلوبة', 'string.min': 'النظرة العامة قصيرة جدًا' }),
    // Empty → generated from overview by the service layer.
    shortDescription: optionalText(500),
    outputs: textList('المخرجات'),
    methodology,
    targetAudience: textList('الفئة المستهدفة'),
    // Parts of the center that are not catalog services: shown on the center page only.
    extraServices: titledList('خدمات ضمن المركز', 'خدمة'),
    serviceIds: Joi.array().items(Joi.number().integer().positive())
        .unique().max(MAX_LIST_ITEMS).default([])
        .messages({ 'array.unique': 'تم اختيار نفس الخدمة أكثر من مرة', 'number.base': 'معرّف خدمة غير صالح' }),
});

export const centerFilterSchema = Joi.object({
    status: Joi.string().valid(...CENTER_STATUSES),
    search: Joi.string().trim().max(100).allow(''),
});
